  if (d16_allowed && inst->d16)
    words = (words + 1) / 2;
  // A dropped fetch with DMASK=0 cannot produce TFE status. LWE
  // can still return status for sampler operations. Both flags
  // share one status word; stores do not consume that word.
  bool status = false;
